export const whereToEatData: EatEntry[] = raw.map((r) => {
  const meta = destMeta[r.destSlug] ?? { name: r.destSlug, country: "", heroImage: "" };
  return { ...r, destName: meta.name, destCountry: meta.country, destHero: meta.heroImage };
});

export const EAT_CUISINES = [...new Set(whereToEatData.map((e) => e.cuisine))].sort();
